add_action( 'woocommerce_product_options_pricing', 'perfectpixel_rrp_field' );
add_action( 'woocommerce_admin_process_product_object', 'perfectpixel_rrp_save' );
add_action( 'woocommerce_single_product_summary', 'perfectpixel_rrp_output', 11 );

function perfectpixel_rrp_field() {
	woocommerce_wp_text_input(
		array(
			'id'        => '_perfectpixel_rrp',
			'label'     => 'Προτεινόμενη τιμή λιανικής (' . get_woocommerce_currency_symbol() . ')',
			'data_type' => 'price',
		)
	);
}

function perfectpixel_rrp_save( $product ) {
	if ( isset( $_POST['_perfectpixel_rrp'] ) ) {
		$product->update_meta_data( '_perfectpixel_rrp', wc_format_decimal( wp_unslash( $_POST['_perfectpixel_rrp'] ) ) );
	}
}

function perfectpixel_rrp_output() {
	global $product;
	if ( ! $product || $product->is_type( 'variable' ) ) {
		return;
	}
	$rrp = (float) $product->get_meta( '_perfectpixel_rrp' );
	if ( $rrp > 0 ) {
		echo '<p class="perfectpixel-rrp" style="opacity:.75">' . esc_html( '{{rrp_label}}' ) . ' <del>' . wp_kses_post( wc_price( $rrp ) ) . '</del></p>';
	}
}
